"""LSTM-TrajGAN: GPS trajectories, one per test move, generated by rewriting that move."""
from __future__ import annotations

import numpy as np
import pandas as pd

from evaluation.tables import GPS_COLUMNS, Converted

MODEL = "lstm_trajgan"
NETWORK = "tstrajgen"  # road tables come from FMM on TS-TrajGen's network, so road IDs are geo_ids


def convert(files: dict, options: dict) -> Converted:
    """Read LSTM-TrajGAN's generated CSV and its real test and training CSVs and return the common format.

    Each file has one row per point with columns label, tid, lat, lon, day, hour, category. A generated trajectory keeps
    the tid of the real move it rewrote, so ref_id = tid. Only day and hour survive, so there is no time within a
    trajectory (t_s is NaN). The road tables are added afterwards from FMM matches of these GPS tables (fmm_prepare.py).
    """
    generated = _points(files["generated"], prefix=f"{MODEL}:", group="main", with_ref=True)
    real = _points(files["real_test"], prefix="", group="real_test", with_ref=False)
    train = _points(files["real_train"], prefix="", group="real_train", with_ref=False)


    return Converted(
        model=MODEL,
        generated=generated,
        real=real,
        train=train,
        unit="move",
        notes={"time": "day and hour only, no time within a trajectory"},
    )


def _points(path, prefix: str, group: str, with_ref: bool) -> pd.DataFrame:
    """Read one LSTM-TrajGAN point CSV into a GPS table, keeping the file's point order."""
    df = pd.read_csv(path, usecols=["tid", "lat", "lon"])
    tid = df["tid"].astype(str)
    return pd.DataFrame({
        "traj_id": prefix + tid,
        "group": group,
        "ref_id": tid if with_ref else None,
        "seq": df.groupby("tid", sort=False).cumcount().to_numpy(),
        "lat": df["lat"].astype(float),
        "lng": df["lon"].astype(float),
        "t_s": np.nan,
    })[GPS_COLUMNS]
